with alvo(i,t) as (values (0,'bauru'),(1,'misto quente'),(2,'x burguer'),(3,'x salada'),(4,'x frango'),(5,'x egg'),(6,'x bacon'),(7,'x calabresa'),(8,'x file'),(9,'x frango'),(10,'x burguer'),(11,'x tudo'),(12,'x big'),(13,'x file'),(14,'bagunca'),(15,'bagunca'),(16,'hot dog'),(17,'refrigerante lata'),(18,'refrigerante 600'),(19,'refrigerante 2'),(20,'h2o'),(21,'agua com gas'),(22,'agua sem gas'),(23,'suco de laranja'),(24,'brahma zero'),(25,'skol lata'),(26,'pastel de carne'),(27,'pastel de carne com queijo'),(28,'pastel de presunto'),(29,'pastel de frango com catupiry'),(30,'pastel misto'),(31,'pastel de queijo'),(32,'pastel de carne seca'),(33,'pastel de carne seca'),(34,'mini pizza'),(35,'mini pizza'),(36,'mini pizza'),(37,'caldo de costela'),(38,'caldo de feijao'),(39,'caldo de frango'),(40,'mocoto'),(41,'batata frita'),(42,'calabresa acebolada'),(43,'file com fritas'),(44,'porcao mista'),(45,'kibe'),(46,'torresm'),(47,'executivo'),(48,'marmitex'),(49,'espeto'),(50,'espeto completo'),(51,'suco de laranja'),(52,'jarra'),(53,'jarra'),(54,'suco'),(55,'com leite'),(56,'jarra'),(57,'jarra')), c as (select a.i, p.image, count(distinct p.establishment_id) n from alvo a join products p on translate(lower(p.name),'áàãâéêíóôõúç-','aaaaeeiooouc ') like '%'||a.t||'%' and coalesce(p.image,'')<>'' and p.image !~* 'supabase' and p.establishment_id not in (1,329,330) group by a.i,p.image), r as (select *, row_number() over (partition by i order by n desc, image) rk from c) select json_agg(json_build_object('i',i,'u',image) order by i,rk) from r where rk<=4;
